import com.gymie.groupsession.core.domain.groupsession.specification.ViewerAccess
import com.gymie.workout.core.domain.workout.WorkoutStatus
import com.gymie.workout.infrastructure.presentation.web.dto.WorkoutSummaryResponse
import jakarta.validation.Valid
import jakarta.validation.constraints.NotEmpty
import jakarta.validation.constraints.NotNull
import java.time.Instant
import java.time.LocalDate
import java.time.LocalTime
import java.util.Optional
import java.util.UUID

data class ParticipantRequestDto(
    @field:NotNull val userId: UUID?,
    @field:NotNull val workoutId: UUID?,
)

data class CreateGroupSessionRequest(
    val name: String? = null,
    @field:NotNull(message = "Scheduled date is required")
    val scheduledDate: LocalDate?,
    val scheduledTime: String? = null,
    @field:NotNull
    @field:NotEmpty(message = "At least one participant is required")
    @field:Valid
    val participants: List<ParticipantRequestDto>?,
)

/**
 * The [PatchWorkoutRequest][com.gymie.workout.infrastructure.presentation.web.dto.PatchWorkoutRequest]
 * `Optional<String>?` shape, applied to both `name` and `scheduledTime`: the outer `?` is `null`
 * when the key is absent, `Optional.empty()`/`Optional.of(raw)` when it is present. `scheduledDate`
 * carries no such distinction -- it is absent or a date, never an explicit `null`.
 */
data class PatchGroupSessionRequest(
    val name: Optional<String>? = null,
    val scheduledDate: LocalDate? = null,
    val scheduledTime: Optional<String>? = null,
)

data class AddParticipantRequest(
    @field:NotNull val userId: UUID?,
    @field:NotNull val workoutId: UUID?,
)

data class ParticipantUserResponse(
    val userId: UUID,
    val displayName: String,
    val slug: String,
    val avatarUrl: String?,
    val gender: String?,
)

data class ParticipantProgressResponse(
    val setsConfirmed: Int,
    val setsTotal: Int,
    val ready: Boolean,
    val finished: Boolean,
)

data class ParticipantResponse(
    val user: ParticipantUserResponse,
    val workout: WorkoutSummaryResponse,
    val progress: ParticipantProgressResponse,
    val viewerCanDrive: Boolean,
)

data class GroupSessionResponse(
    val id: UUID,
    val ownerId: UUID,
    val name: String?,
    val displayName: String,
    val scheduledDate: LocalDate,
    @field:JsonFormat(pattern = "HH:mm")
    val scheduledTime: LocalTime?,
    val status: GroupSessionStatus,
    val startedAt: Instant?,
    val finishedAt: Instant?,
    val viewerAccess: SessionAccess,
    val participants: List<ParticipantResponse>,
)

data class ParticipantReadinessResponse(
    val user: ParticipantUserResponse,
    val progress: ParticipantProgressResponse,
)

data class GroupSessionFinishReadinessResponse(
    val participants: List<ParticipantReadinessResponse>,
)

data class ParticipantWorkoutStateResponse(
    val workoutId: UUID,
    val status: WorkoutStatus,
    val setsConfirmed: Int,
    val setsTotal: Int,
    val blocksCompleted: Int,
    val blocksTotal: Int,
    val updatedAt: Instant,
)

data class ParticipantStateResponse(
    val userId: UUID,
    val position: Int,
    val leftAt: Instant?,
    val viewerAccessToParticipant: ViewerAccess,
    val workout: ParticipantWorkoutStateResponse?,
)

data class GroupSessionLifecycleResponse(
    val status: GroupSessionStatus,
    val startedAt: Instant?,
    val finishedAt: Instant?,
    val updatedAt: Instant,
)

data class GroupSessionStateResponse(
    val serverTime: Instant,
    val session: GroupSessionLifecycleResponse,
    val participants: List<ParticipantStateResponse>,
)

/** `GET /api/group-sessions?from&to` -- the viewer's sessions grouped by day, the week read's own summary shape per session. */
data class GroupSessionDaysResponse(
    val days: List<GroupSessionDayResponse>,
)

data class GroupSessionDayResponse(
    @field:JsonFormat(pattern = "yyyy-MM-dd")
    val date: LocalDate,
    val groupSessions: List<GroupSessionSummaryResponse>,
)

/** `GET /api/group-sessions` -- one session as the viewer sees it, `:groupsession`'s own wire shape. */
data class GroupSessionSummaryResponse(
    val id: UUID,
    val displayName: String,
    @field:JsonFormat(pattern = "HH:mm")
    val scheduledTime: LocalTime?,
    val status: GroupSessionStatus,
    val participantCount: Int,
    val avatarUrls: List<String?>,
    val participantDisplayNames: List<String>,
    val viewerParticipates: Boolean,
