input.new_string:
    @ExceptionHandler(WorkoutStaleException::class)
    fun handleStale(ex: WorkoutStaleException): ProblemDetail =
        ProblemDetail
            .forStatusAndDetail(HttpStatus.CONFLICT, ex.message ?: "Workout changed")
            .apply { setProperty("etag", ETagWebConverter.toETag(ex.currentUpdatedAt)) }

    /**
     * The floor's compare-and-set refusal (decision `value-compare-and-set`, KAN-757). `updatedBy` and
     * `updatedAt` are omitted for a set no PATCH has stamped, for the same `NON_EMPTY` reason as
     * [handleConflict]'s actors.
     */
    @ExceptionHandler(WorkoutSetChangedException::class)
    fun handleSetChanged(ex: WorkoutSetChangedException): ProblemDetail {
        val current = ex.current
        return ProblemDetail
            .forStatusAndDetail(HttpStatus.CONFLICT, "This set was changed on another phone.")
            .apply {
                setProperty("code", "set_changed")
                setProperty(
                    "current",
                    mapOf(
                        "weight" to SetWeightWebConverter.toDto(current.weight),
                        "effort" to SetEffortWebConverter.toDto(current.effort),
                        "confirmed" to (current.confirmedAt != null),
                    ),
                )
                current.updatedBy?.let { setProperty("updatedBy", actorOf(it)) }
                current.updatedAt?.let { setProperty("updatedAt", it) }
            }
    }
}

