import java.time.Instant
import java.util.UUID

@WebMvcTest(controllers = [GroupSessionWorkoutController::class])
@Import(
    GroupSessionWorkoutController::class,
    GroupSessionExceptionHandler::class,
    WorkoutExceptionHandler::class,
    GroupSessionFloorSetConflictTest.TestConfig::class,
)
class GroupSessionFloorSetConflictTest {
    @Autowired lateinit var mockMvc: MockMvc

    @Autowired lateinit var groupSessionQueryService: GroupSessionQueryService

    @Autowired lateinit var workoutFieldPatchService: WorkoutFieldPatchService

    private val owner = UUID.fromString("11111111-1111-1111-1111-111111111111")
    private val jana = UUID.fromString("22222222-2222-2222-2222-222222222222")
    private val sessionId = UUID.randomUUID()
    private val workoutId = UUID.randomUUID()
    private val setId = UUID.randomUUID()

    @BeforeEach
    fun resetMocks() {
        clearMocks(groupSessionQueryService, workoutFieldPatchService)
        every { groupSessionQueryService.participantWorkoutIdForWrite(owner, sessionId, jana) } returns workoutId
    }

    private fun setPath() = "/api/group-sessions/$sessionId/participants/$jana/workout/sets/$setId"

    @Test
    fun `expected reaches the service as SetValues with the driver as actor`() {
        val expected = SetValues(SetWeight.Measured(BigDecimal("60")), SetEffort.Count(8), confirmed = false)
        every {
            workoutFieldPatchService.patchSet(jana, workoutId, setId, null, null, true, owner, expected)
        } throws WorkoutSetChangedException(WorkoutSet(id = setId, position = 0))

        mockMvc
            .patch(setPath()) {
                with(user(owner.toString()))
                with(csrf())
                contentType = MediaType.APPLICATION_JSON
                content =
                    """{"weight":null,"effort":null,"confirmed":true,
                        "expected":{"weight":{"kind":"MEASURED","value":60},"effort":{"kind":"COUNT","value":8},"confirmed":false}}"""
            }.andExpect { status { isConflict() } }

        verify { workoutFieldPatchService.patchSet(jana, workoutId, setId, null, null, true, owner, expected) }
    }

    @Test
    fun `a stamped set changed by someone else answers 409 set_changed with current and its author`() {
        val stamped =
            WorkoutSet(
                id = setId,
                position = 0,
                weight = SetWeight.Measured(BigDecimal("62.5")),
                effort = SetEffort.Count(10),
                confirmedAt = Instant.parse("2026-10-14T09:00:00Z"),
                updatedAt = Instant.parse("2026-10-14T09:00:05Z"),
                updatedBy = owner,
            )
        every { groupSessionQueryService.profileOf(owner) } returns ParticipantProfile(owner, "Mira Kovac", "mira", null, null)
        every {
            workoutFieldPatchService.patchSet(jana, workoutId, setId, null, null, true, owner, any())
        } throws WorkoutSetChangedException(stamped)

        mockMvc
            .patch(setPath()) {
                with(user(owner.toString()))
                with(csrf())
                contentType = MediaType.APPLICATION_JSON
                content =
                    """{"weight":null,"effort":null,"confirmed":true,
                        "expected":{"weight":{"kind":"MEASURED","value":60},"effort":{"kind":"COUNT","value":8},"confirmed":false}}"""
            }.andExpect {
                status { isConflict() }
                jsonPath("$.code") { value("set_changed") }
                jsonPath("$.detail") { value("This set was changed on another phone.") }
                jsonPath("$.current.weight.kind") { value("MEASURED") }
                jsonPath("$.current.weight.value") { value(62.5) }
                jsonPath("$.current.effort.kind") { value("COUNT") }
                jsonPath("$.current.effort.value") { value(10) }
                jsonPath("$.current.confirmed") { value(true) }
                jsonPath("$.updatedBy.id") { value(owner.toString()) }
                jsonPath("$.updatedBy.displayName") { value("Mira Kovac") }
                jsonPath("$.updatedAt") { value("2026-10-14T09:00:05Z") }
            }
    }

    @Test
    fun `an unstamped set answers 409 set_changed with no author or time`() {
        val unstamped =
            WorkoutSet(
                id = setId,
                position = 0,
                weight = null,
                effort = null,
                confirmedAt = null,
            )
        every {
            workoutFieldPatchService.patchSet(jana, workoutId, setId, null, null, true, owner, any())
        } throws WorkoutSetChangedException(unstamped)

        mockMvc
            .patch(setPath()) {
                with(user(owner.toString()))
                with(csrf())
                contentType = MediaType.APPLICATION_JSON
                content =
                    """{"weight":null,"effort":null,"confirmed":true,
                        "expected":{"weight":null,"effort":null,"confirmed":false}}"""
            }.andExpect {
                status { isConflict() }
                jsonPath("$.code") { value("set_changed") }
                jsonPath("$.current.confirmed") { value(false) }
                jsonPath("$.updatedBy") { doesNotExist() }
                jsonPath("$.updatedAt") { doesNotExist() }
            }
    }

    @Test
    fun `an unknown field on the floor set body answers 400`() {
        mockMvc
            .patch(setPath()) {
                with(user(owner.toString()))
                with(csrf())
                contentType = MediaType.APPLICATION_JSON
                content = """{"weight":null,"effort":null,"confirmed":true,"foo":1}"""
            }.andExpect { status { isBadRequest() } }

        verify(exactly = 0) { workoutFieldPatchService.patchSet(any(), any(), any(), any(), any(), any(), any(), any()) }
    }

    @TestConfiguration
    class TestConfig {
        @Bean
        fun groupSessionQueryService(): GroupSessionQueryService = mockk()

        @Bean
        fun workoutService(): WorkoutService = mockk()

        @Bean
        fun workoutFieldPatchService(): WorkoutFieldPatchService = mockk()

        @Bean
        fun workoutFinishReadinessService(): WorkoutFinishReadinessService = mockk()

        @Bean
        fun workoutResponseAssembler(): WorkoutResponseAssembler = mockk()
    }
}

